yakit.AutoInitYakit()

# Input your code!

whiteHosts = cli.Text("whiteHosts", cli.setHelp("按行分隔会与数据包中的Host做关键字匹配,支持global语法"), cli.setVerboseName("Host白名单"))
blackHosts = cli.Text("blackHosts", cli.setHelp("按行分隔,会与数据包中的Host做关键字匹配,支持global语法"), cli.setVerboseName("Host黑名单"))
skip =cli.Bool("skip",cli.setVerboseName("跳过插件流量"),cli.setDefault(true))
cli.check()

count := 0//记录检查的流量个数
out := 0//记录忽略的流量个数
all_path = container.NewSet()//子路径+完整路径
sub_path = container.NewSet()//子路径
long_path = container.NewSet()//完整路径
path_word = container.NewSet()//路径中的单词
parameter = container.NewSet()//数据包的参数
isMap = (v) => { return str.Contains(typeof(v).String(), "Map") }
//传入一个json，递归获取Key并加进parameter中
getJsonKey = func(jsn) {
    for key, value = range jsn {
        if key != "" && typeof(key) != int {
            parameter.Add(string(key))
        }
        

        if typeof(value) != string && typeof(value) != int && typeof(value) != float && typeof(value) != bool {
            if value != nil {
                getJsonKey(value)
            }
        }
    }
}
//传入str.ParseStringUrlToUrlInstance(flow.URL)~.Path，解析出路径和单词放到全局变量中
jiekou = func(path) {
    sli = str.Split(path, "/")
    tmp = ""
    for index, value = range (sli) {
        if value == "" {
            continue
        }
        

        tmp += "/" + value
        if len(sli) - 1 == index {
            long_path.Add(tmp)
        } else {
            sub_path.Add(tmp)
        }
        

        all_path.Add(tmp)
        path_word.Add(value)
    }
}

//输出结果函数
output = func(str_name, container_result) {
    yakit.EnableText(str_name)
    output_str = ""
    container_result.Each(func(i) {
        if str.IsAllVisibleASCII(i) {
            output_str += i + "\n"
        }
    })
    yakit.TextTabData(str_name, output_str)
    yakit.Text(output_str)
}

//过滤器
filter = func(flow) {
    url = flow.Url
    info = ""
    defer println(url + " " + info)
    if flow.SourceType != "mitm" {
        if skip{
            info = f"${flow.FromPlugin} 插件流量,跳过"
            return false
        }
        
    }
    

    if !str.StringContainsAnyOfSubString(flow.Method, ["GET", "POST", "PUT", "DELETE"]) {
        info = f"${flow.Method} 不是常规请求方法,跳过"
        return false
    }
    


    tmppath,er1=str.ParseStringUrlToUrlInstance(url)
    if er1{
        return false
    }
//排除Path存在如下关键字的数据包
    noext = ['.vue', '.ts', '.css', '.svg', '.webp', '.woff2', '.mp4', '.png', '.jpg', '.jpeg', '.gif', '.ico', '.bmp', '.tiff', '.ttf', '.otf', '.eot', '.wav', '.mp3', '.ogg', '.avi', '.mov', '.wmv', '.flv', '.mkv', '.map', 'webpack-hmr', '__vite_ping', '__webpack_hmr', '.ws', '.wss', 'javascript:', 'data:image', ';base64', 'blob:', 'about:', 'mailto:', 'tel:']
    if str.StringContainsAnyOfSubString(
        tmppath.Path, 
        noext, 
    ) {
        info = "关键字排除，跳过"
        return false
    }
    # 静态文件后缀列表
    staticFileSuffixes = [".css", ".jpg", ".jpeg", ".png", ".gif", ".wmv", ".a3c", ".ace", ".aif", ".aifc", ".aiff", ".arj", ".asf", ".asx", ".attach", ".au", ".avi", ".bin", ".bmp", ".cab", ".cache", ".class", ".djv", ".djvu", ".dwg", ".es", ".esl", ".exe", ".fif", ".fvi", ".gz", ".hqx", ".ice", ".ico", ".ief", ".ifs", ".iso", ".jar", ".jpe", ".kar", ".mdb", ".mid", ".midi", ".mov", ".movie", ".mp", ".mp2", ".mp3", ".mp4", ".mpeg", ".mpeg2", ".mpg", ".mpg2", ".mpga", ".msi", ".pac", ".pdf", ".ppt", ".psd", ".qt", ".ra", ".ram", ".rar", ".rm", ".rpm", ".snd", ".svf", ".tar", ".tgz", ".tif", ".tiff", ".tpl", ".ttf", ".uff", ".wav", ".wma", ".zip", ".woff", ".woff2", ".apk",".js"]
    for  i in staticFileSuffixes{
        if str.EndsWith(str.ParseStringUrlToUrlInstance(url)~.Path,i){
            info = "后缀排除，跳过"
            return false
        }
    }
    

    w = str.ParseStringToLines(whiteHosts)
    b = str.ParseStringToLines(blackHosts)
    addr=str.ParseStringUrlToUrlInstance(url)~.Host
    // 使用 global 语法检查白名单  
    if len(w) > 0 && !str.MatchAnyOfGlob(addr, w...) {  
        println(f"${addr}不在白名单内,跳过扫描")  
        return  false
    }  
    
    // 使用 global 语法检查黑名单  
    if str.MatchAnyOfGlob(addr, b...) {  
        println(f"${addr}在黑名单内,跳过扫描")  
        return  false
    }
    

    return true
}

yakitFlow = yakit.QueryHTTPFlowsAll()
////////////////////////////////////
for flow in yakitFlow {
    if filter(flow) {
        method := flow.Method

        //获取get请求的参数
        if method == "GET" {
            params = poc.GetAllHTTPPacketQueryParams(flow.GetRequest())
            for i in params.Keys() {
                parameter.Add(i)
            }
        } else if method == "POST" {
            req, err = poc.ParseBytesToHTTPRequest(flow.GetRequest())
            if !err {
                if str.Contains(string(req.Header["Content-Type"]), "application/json") {
                    body = str.TrimSuffix(str.TrimPrefix(string(req.Body), "{"), "}")
                    try {
                        body_json = json.loads(body)
                        // yakit.Info(string(body_json)+"      长度"+string(len(body_json))+"   键"+string(body_json.Keys()))
                        if (isMap(body_json) && len(body_json) > 0) {
                            getJsonKey(body_json)
                        }
                    } catch err {
                        println(string(err))
                    }
                }
            }
            







//处理POST请求包
            params, err = poc.ExtractPostParams(flow.GetRequest())
            if !err {
                for i in params.Keys() {
                    match = re.FindGroup(i, `^(\w+)\[([\w@]+)\]$`)
                    if len(match) != 0 {
                        for key, value = range match {
                            if value != i {
                                parameter.Add(value)
                            }
                        }
                    } elif i != "" {
                        parameter.Add(i)
                    }
                }
            }
        }







//处理Json格式的响应包
        fuck_here, err = poc.ParseBytesToHTTPResponse(flow.GetResponse())
        if !err {
            if str.Contains(string(fuck_here.Header["Content-Type"]), "application/json") {
                body = str.TrimSuffix(
                    str.TrimPrefix(string(fuck_here.Body), "{"), 
                    "}", 
                )
                try {
                    body_json = json.loads(body)
                    //如果响应包可以成功被加载成json格式，则提取参数名
                    if (isMap(body_json) && len(body_json) > 0) {
                        getJsonKey(body_json)
                    }
                } catch err {
                    println(string(err))
                }
            }
        }
        






//提取URL路径的单词
        path = str.ParseStringUrlToUrlInstance(flow.Url)~.Path
        jiekou(path)

        count += 1
        yakit.StatusCard("进度", f"已检查${count}个数据包")
        ###################################
    } else {
        out += 1
        yakit.StatusCard("过滤", f"已忽略${out}个数据包")
    }
}


output("完整路径", long_path)
output("提取的子路径", sub_path)
output("子路径+完整路径", all_path)
output("URL路径中提取的单词", path_word)
output("历史流量中提取的参数", parameter)
